import sys
from bisect import bisect_left

def longest_increasing_subsequence(a):
    n = len(a)
    lis = []
    prev_index = [-1] * n
    count = [1] * n

    for i in range(n):
        pos = bisect_left(lis, a[i])
        if pos == len(lis):
            lis.append(a[i])
        else:
            lis[pos] = a[i]

        if pos > 0:
            prev_index[i] = bisect_left(lis, a[i]) - 1

        if pos < len(lis) - 1:
            count[i] = count[prev_index[i]] + 1

    return lis, prev_index, count

def find_lis_elements(a, lis, prev_index, count):
    n = len(a)
    max_length = len(lis)
    result = ['0'] * n

    def backtrack(i, current_lis):
        if i == -1:
            if len(current_lis) == max_length:
                for idx in current_lis:
                    result[idx] = '3'
            elif len(current_lis) > 0:
                for idx in current_lis:
                    if result[idx] != '3':
                        result[idx] = '2'
            return

        backtrack(prev_index[i], current_lis + [i])
        if count[i] > 1:
            backtrack(prev_index[i], current_lis)

    for i in range(n):
        if count[i] == max_length:
            backtrack(i, [])

    for i in range(n):
        if result[i] == '0':
            result[i] = '1'

    return ''.join(result)

